"use client";
import { CircleDot, TerminalSquare } from "lucide-react";
export default function AgentTerminal({ logs, isAuditing }: { logs: string[]; isAuditing: boolean }) { return <section className="panel flex min-h-[342px] flex-col overflow-hidden"><div className="flex items-center justify-between border-b border-slate-800 px-4 py-3"><div className="flex items-center gap-2"><TerminalSquare size={15} className="text-cyan-300" /><h2 className="panel-title">Live agent stream</h2></div><span className="flex items-center gap-1.5 font-mono text-[10px] text-cyan-300"><CircleDot size={11} className={isAuditing ? "animate-pulse" : ""} /> SSE / CONNECTED</span></div><div className="relative flex-1 overflow-hidden bg-[#080c13] p-4 font-mono text-[11px] leading-6"><div className="absolute inset-0 opacity-[0.035] terminal-grid" /><div className="relative space-y-1">{logs.map((log, i) => <div key={`${log}-${i}`} className="terminal-line animate-in" style={{ animationDelay: `${i * 65}ms` }}><span className="mr-3 text-slate-600">{String(i + 1).padStart(2, "0")}</span><span className={log.includes("Risk") || log.includes("headwinds") ? "text-amber-300" : log.includes("Technical") || log.includes("ESG") ? "text-emerald-300" : "text-slate-300"}>{log}</span></div>)}{isAuditing && <div className="flex items-center gap-2 text-cyan-300"><span className="text-slate-600">0{logs.length + 1}</span><span className="size-1.5 animate-pulse rounded-full bg-cyan-300" /> Awaiting agent response<span className="animate-pulse">...</span></div>}</div></div><div className="flex items-center justify-between border-t border-slate-800 bg-slate-950/70 px-4 py-2 font-mono text-[10px] text-slate-500"><span>PIPELINE: <b className="font-medium text-emerald-300">5/5 COMPLETED</b></span><span>LATENCY: 1.24s</span></div></section>; }
